  "enunciado": "Uma pessoa necessita armazenar uma quantidade V de líquido e possui um recipiente no formato de cilindro circular reto, com raio da base medindo r minúsculo, o qual comporta apenas quatro nonos dessa quantidade. Essa pessoa comprou, então, um novo recipiente no mesmo formato, com raio da base medindo R maiúsculo, mantendo a mesma medida da área lateral do primeiro recipiente, e que comporta exatamente a quantidade V de líquido.\n\nA razão fração de numerador R maiúsculo e denominador r minúsculo entre os raios dos dois recipientes é",
