  "enunciado": "O índice de massa corporal é uma medida internacional usada para determinar se uma pessoa está com a massa corporal ideal. No cálculo do índice de massa corporal, são utilizadas a massa corporal da pessoa, em quilograma, e a sua altura, em metro. O valor do índice de massa corporal é dado pela razão entre a massa do indivíduo pelo quadrado de sua altura.\n\nA unidade de medida do índice de massa corporal é",
