  "enunciado": "Esteiras e escadas rolantes são dispositivos que deslocam, a velocidade constante, os objetos neles colocados, por meio de sistemas de controle com sensores. Quando a massa total do dispositivo varia, seja pelo acréscimo ou pela retirada de objetos, a ação de forças impulsivas mantém a velocidade constante. Como exemplo, considere que a massa total diminua de 1 200 quilogramas para 1 000 quilogramas em um intervalo de tempo de 0,10 segundo, e que, então, seja aplicada uma força impulsiva constante de 250 newtons para manter constante a velocidade. No exemplo mencionado, o valor da velocidade constante do dispositivo rolante é, em metro por segundo,",
