  "enunciado": "O crescimento populacional foi um importante motivo para o avanço no desenvolvimento tecnológico a fim de aumentar a produtividade agrícola e controle de pragas que danificam a produção. No entanto, o uso indiscriminado de determinadas substâncias pode gerar consequências graves ao ambiente. Essas consequências estão relacionadas especificamente à prática de",
