  "enunciado": "Notícias veiculadas em diferentes meios de comunicação vêm mostrando que no Brasil há um aumento significativo no número de infecções sexualmente transmissíveis (ISTs) entre jovens, assim como a incidência de casos de gravidez na adolescência acima da média latino-americana, segundo dados da Organização Mundial da Saúde (OMS). Uma campanha com o objetivo de mostrar que é possível prevenir as duas situações com o uso de um só método deve incentivar o uso de",
