  "enunciado": "A curiosidade humana sobre a origem e o desenvolvimento da vida no planeta gerou várias teorias. Uma delas postulava que:\n• as unhas do bicho-preguiça viraram garras enormes em cada dedo, de tanto se agarrarem às árvores;\n• morcegos perderam a visão porque moravam em cavernas escuras onde era impossível enxergar;\n• de tanto pular de galho em galho, o rabo dos macacos tornou-se preênsil. Essas explicações eram aceitas como mecanismo de evolução na",
