  "enunciado": "Uma região apresenta grande potencial para geração de energia. Por lá passa um rio que tem uma grande queda-d’água. O vento é constante e não há rotas migratórias de pássaros. O plantio de árvores de reflorestamento para produção de carvão cobre uma vasta área. Além disso, o acesso é fácil e não há histórico de tremor de terra ou qualquer outro tipo de desastre natural. Valendo-se de uma fonte renovável de energia e de pequeno impacto ambiental, pode-se explorar o potencial energético da região, construindo uma usina",
