  "enunciado": "Sementes de algumas espécies de gramíneas são capazes de germinar e colonizar dunas de areia em desertos, regiões de solo arenoso com baixo teor de matéria orgânica, alta temperatura e baixa umidade. Devido a essa capacidade, essas plantas são denominadas pioneiras. Nas condições ambientais citadas, as características das gramíneas que favorecem seu pioneirismo são:",
