  "enunciado": "Numa fazenda, os porcos são alimentados com cascas de legumes produzidos no local. As fezes desses animais são usadas para adubar o pasto que serve de alimento para o gado leiteiro e de corte. O estrume do gado serve como adubo para a horta e a produção de grãos. Na situação descrita, para possibilitar a transferência de energia de um ser vivo a outro, é fundamental o papel dos organismos decompositores sobre os (as)",
