  "enunciado": "Uma empresa que possui carros-pipas, todos com 10 000 litros de capacidade, ganhou a licitação para abastecer uma pequena cidade que está com problemas para captar água para o consumo. Todos os dias, a empresa enche um reservatório de água, no formato de um bloco retangular, de dimensões 60 dm × 80 dm × 50 dm, que fica na praça da cidade, para que a água seja distribuída à população. Considerando que o reservatório esteja vazio, para enchê-lo de água, a quantidade de carros-pipas necessária é igual a",
