  "enunciado": "Antes do Natal, uma loja de eletrodomésticos vendia um televisor por R$ 1 700,00. Como depois do Natal as vendas caíram muito, a loja reduziu o preço desse modelo de televisor e vendeu todo o estoque de 12 unidades, arrecadando, com isso, R$ 14 400,00. Caso vendesse os 12 televisores pelo preço praticado antes do Natal, quantos reais a mais a loja teria arrecadado?",
