  "enunciado": "Um fazendeiro pretende cercar parte de um terreno de sua fazenda com arame, e calculou que precisaria de 840 m desse arame. Ele sabe que uma loja próxima à sua casa dispõe de rolos de arame de 50 m, 100 m, 200 m e 250 m de comprimento. O fazendeiro decide, então, comprar rolos de mesmo comprimento, de modo que a sobra fosse a menor possível. Qual deve ser o comprimento, em metro, do rolo de arame a ser comprado pelo fazendeiro?",
