  "enunciado": "Para o uso sustentável da água, recomenda-se que as plantas e o gramado de um jardim sejam molhados antes das 10 horas da manhã e após as 19 horas. Assim, garante-se a manutenção da umidade desse jardim, respeitando-se o ciclo da água, sem desperdícios. Essa recomendação considera o fenômeno da",
