  "enunciado": "Para investigar as propriedades dos líquidos, um estudante encheu dois copos de mesmo volume, sendo um com água (copo I) e outro com mel (copo II). Em seguida, ele colocou esferas metálicas idênticas na superfície de cada líquido e mediu o tempo que elas levaram para atingir o fundo do copo. O estudante percebeu que a esfera metálica do copo I chegou ao fundo muito mais rapidamente que a do copo II. Qual propriedade dos líquidos foi responsável pelo resultado observado pelo estudante?",
