  "enunciado": "Um produto, novo no mercado, é utilizado para limpar piscinas. Recomenda-se que, a cada 5 000 litros de água, deva-se diluir 40 g desse produto diretamente na piscina. Uma pessoa deve limpar uma piscina de 40 000 litros. Caso siga corretamente a recomendação, a pessoa deverá diluir",
