  "enunciado": "O projeto original de uma residência previa a construção de uma piscina retangular com as seguintes dimensões: 9 metros de comprimento, 5 metros de largura e 1,8 metro de profundidade. Devido à existência de tubulação no subsolo da residência, a profundidade dessa piscina teve que ser limitada a 1,5 metro. O proprietário aprovou a construção da piscina com essa profundidade, desde que seu comprimento e capacidade (volume) originais fossem mantidos e solicitou ao engenheiro responsável uma adequação no projeto. A largura da piscina, em metro, informada pelo engenheiro no novo projeto é",
