  "enunciado": "Uma pessoa necessita de um empréstimo de R$ 10 000,00. Uma instituição financeira oferece empréstimos a uma taxa de juros simples de 2% ao mês, sendo que a dívida gerada pelo empréstimo deve ser liquidada em uma única parcela, paga ao final do último mês do contrato. Essa pessoa pretende pagar, no máximo, R$ 11 000,00 na liquidação dessa dívida. O prazo máximo, em quantidade de meses, que deverá durar esse contrato é",
