  "enunciado": "Em um dos setores de uma indústria alimentícia, 5 máquinas permanecem ligadas durante 10 horas diárias para embalar salgadinhos de milho em pacotes, sendo que cada máquina produz 500 pacotes por hora. Em um determinado dia, uma das máquinas foi paralisada para manutenção preventiva, não participando da produção daquele dia, o que fez com que as demais máquinas tivessem que funcionar por um período maior de tempo para manter a produção diária habitual dessa indústria. Para que a produção diária habitual dessa indústria se mantenha, essas máquinas deverão funcionar, nesse dia, pelo tempo de",
