  "enunciado": "Em uma escola, foram comprados 120 m de tela. Toda essa tela deverá ser usada para cercar duas regiões quadradas: um galinheiro e uma horta. A fim de evitar que as aves comam as hortaliças, o galinheiro e a horta não terão fronteiras em comum. A direção da escola quer que a soma das áreas das duas regiões seja a maior possível, sendo que o lado do galinheiro deve medir, pelo menos, 14 m, enquanto o lado da horta deve medir, pelo menos, 13 m. Suponha que, além disso, deseja-se que os comprimentos dos lados de ambas as regiões sejam números inteiros. Qual deverá ser a medida, em metro, do lado do galinheiro para se atingir esse objetivo?",
