  "enunciado": "Observe as ações:\n• Escovar os dentes com a torneira aberta.\n• Tomar banhos demorados.\n• Limpar a calçada com uso de mangueira.\n• Lavar o carro com uso de mangueira.\n• Ensaboar a louça suja com a torneira aberta. Todas as ações descritas estão relacionadas ao desperdício de água e são alvos de inúmeras campanhas que apontam a necessidade de economia desse recurso, cada vez mais escasso. Considerando as ações descritas, indique a medida que melhor sintetizaria a proposta para a economia de água a ser adotada nos casos citados:",
